import { cookies, headers } from 'next/headers';

export default async function Home() {
  const cookieStore = await cookies();
  const headersList = await headers();

  const theme = cookieStore.get('theme')?.value || 'light';

  const acceptLanguage = headersList.get('accept-language') || 'Not specified';
  const preferredLanguage = acceptLanguage.split(',')[0].trim();

  return (
    <main>
      <h1>User Preferences</h1>

      <section>
        <h2>Theme Preference</h2>
        <p>Current theme: <strong>{theme}</strong></p>
        {!cookieStore.get('theme') && (
          <p><em>(Using default theme)</em></p>
        )}
      </section>

      <section>
        <h2>Language Preference</h2>
        <p>Preferred language: <strong>{preferredLanguage}</strong></p>
        <p>Full Accept-Language header: {acceptLanguage}</p>
      </section>
    </main>
  );
}

